330	struct KernelLaunchOptions {
331	    std::string kernel_name;
332	    uint32_t requested_cores = 0;
333	    uint32_t total_work_items = 0;
334	    uint32_t work_quantum = 1;
335	    uint32_t subblocks_per_block = 1;
336	    uint32_t explicit_block_count = 0;
337	    bool write_trace_files = true;
338	};
