340	inline uint32_t ResolveActiveCoreCount(
341	    uint32_t requested_cores, uint32_t total_work_items = 0, uint32_t work_quantum = 1)
342	{
343	    const uint32_t configured = requested_cores == 0 ? GetConfiguredCoreCount() : requested_cores;
344	    uint32_t active = std::max<uint32_t>(1, configured);
345	    if (total_work_items == 0) {
346	        return active;
347	    }
348	
349	    active = std::max<uint32_t>(1, std::min(active, total_work_items));
350	    const uint32_t quantum = std::max<uint32_t>(1, work_quantum);
351	    while (active > 1) {
352	        const uint32_t chunk = (total_work_items + active - 1) / active;
353	        if (chunk % quantum == 0) {
354	            break;
355	        }
356	        --active;
357	    }
358	    return active;
359	}
