    pto::cpu_sim::LaunchKernelMultiCore(
        {.kernel_name = "optimized", .total_work_items = totalLength, .work_quantum = StandardTileConfig::TILE_SIZE},
        stream, [&]() { FusedAddReLUMulOptimizedKernel(out_ptr, x_ptr, bias, scale, totalLength); });
}

